CREATE TABLE IF NOT EXISTS attendance (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE, student_id UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE, class_id UUID REFERENCES classes(id), attendance_date DATE NOT NULL DEFAULT CURRENT_DATE, status TEXT NOT NULL CHECK(status IN ('present','absent','late','excused')), note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(student_id,attendance_date));
CREATE TABLE IF NOT EXISTS fee_invoices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE, student_id UUID NOT NULL REFERENCES students(id), title TEXT NOT NULL, amount NUMERIC(12,2) NOT NULL CHECK(amount>=0), paid_amount NUMERIC(12,2) NOT NULL DEFAULT 0, due_date DATE, status TEXT NOT NULL DEFAULT 'pending', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE, invoice_id UUID REFERENCES fee_invoices(id), student_id UUID NOT NULL REFERENCES students(id), amount NUMERIC(12,2) NOT NULL CHECK(amount>0), method TEXT NOT NULL DEFAULT 'bank transfer', reference TEXT, paid_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS results (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE, student_id UUID NOT NULL REFERENCES students(id) ON DELETE CASCADE, subject_id UUID REFERENCES subjects(id), term TEXT NOT NULL, session TEXT NOT NULL, ca_score NUMERIC(5,2) NOT NULL DEFAULT 0, exam_score NUMERIC(5,2) NOT NULL DEFAULT 0, total NUMERIC(5,2) NOT NULL DEFAULT 0, grade TEXT, remark TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(student_id,subject_id,term,session));
CREATE TABLE IF NOT EXISTS announcements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE, title TEXT NOT NULL, body TEXT NOT NULL, audience TEXT NOT NULL DEFAULT 'all', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS students_school_class_idx ON students(school_id,class_id);
CREATE INDEX IF NOT EXISTS attendance_school_date_idx ON attendance(school_id,attendance_date);
CREATE INDEX IF NOT EXISTS invoices_school_idx ON fee_invoices(school_id,status);